CREATE OR REPLACE FUNCTION public.kpi_source_value(_cp uuid,_month date,_key text,_avg boolean DEFAULT false) RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $f$ DECLARE val numeric; source_key text; v jsonb; BEGIN source_key:=CASE WHEN _key LIKE 'social.sum.%' THEN substr(_key,12) WHEN _key LIKE 'gbp.%' THEN substr(_key,5) ELSE NULL END; IF source_key IS NOT NULL THEN SELECT coalesce(f.corrected_values,f.fetched_values) INTO v FROM kpi_fetched_values f WHERE f.client_pipeline_id=_cp AND f.month=date_trunc('month',_month)::date AND f.status='approved' ORDER BY approved_at DESC LIMIT 1; IF _key LIKE 'social.sum.%' THEN SELECT sum(e.value::numeric) INTO val FROM jsonb_each_text(v) e WHERE e.key LIKE '%.'||source_key AND e.value ~ '^-?[0-9]+(\.[0-9]+)?$'; IF val IS NOT NULL THEN RETURN val; END IF; ELSIF v ? source_key THEN RETURN (v->>source_key)::numeric; END IF; END IF; RETURN public.kpi_source_value_legacy(_cp,_month,_key,_avg); END $f$;